def download(url, dest):
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    with urllib.request.urlopen(req) as resp, open(dest, 'wb') as f:
        f.write(resp.read())

print(f"Total items to download: {len(dish_images)}")
for fname, hd_url, raw_url in dish_images:
    dest = os.path.join(output_dir, fname)
    print(f"Downloading {fname}...")
    try:
        download(hd_url, dest)
        print(f"  Saved HD version: {fname}")
    except Exception as e:
        print(f"  HD download failed ({e}), falling back to original URL...")
        try:
            download(raw_url, dest)
            print(f"  Saved original version: {fname}")
        except Exception as e2:
            print(f"  Failed completely for {fname}: {e2}")

print("All downloads completed!")
